    ((select id from sermons where service_date = '2026-08-23' and title = 'Living Under The Rule Of The KING'), 3, E'You have found it. Whether you believe it or not.', E'the pearl is inside you', '~6:00', '{reel,short,carousel}', 'to_caption', false, null, null),
    ((select id from sermons where service_date = '2026-08-23' and title = 'Living Under The Rule Of The KING'), 4, E'At best, our response is timid. At best, lukewarm. At best, civilised.', E'the Christian dilemma', '~9:22', '{reel,short,carousel}', 'to_caption', true, E'Diagnosis of the room. Frame as invitation, not rebuke - it lands as a telling-off if cut short.', null),
