    ((select id from sermons where service_date = '2026-08-23' and title = 'Living Under The Rule Of The KING'), 6, E'If you hear his word and you don''t obey it, he''s not ruling. You are ruling.', E'obedience / authority', '~18:40', '{reel,short,carousel}', 'to_caption', false, null, null),
    ((select id from sermons where service_date = '2026-08-23' and title = 'Living Under The Rule Of The KING'), 7, E'One soul is worth more to Him than the whole world. Now hold your circumstance next to that.', E'value of the soul', '~3:41', '{reel,carousel}', 'to_caption', false, null, null),
